import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { FaCalendarAlt, FaBookOpen, FaGraduationCap } from 'react-icons/fa';
import '../App.css';
import '../styles/Home.css';

const Home = () => {
    const navigate = useNavigate();
    const [date] = useState(new Date());

    const [showCourses, setShowCourses] = useState(false);
    const [hoveredCourseId, setHoveredCourseId] = useState(null);

    const courses = [
        { id: 1, title: "B.Sc InformationTechnology", description: "Learn software development, networking, and database management." },
        { id: 2, title: "Management Marketing", description: "Master strategies for brand management and market analysis." },
        { id: 3, title: "Finance Managenment", description: "Understand financial planning, investment strategies, and corporate finance." },
        { id: 4, title: "B.Commerce", description: "Comprehensive study of business, accounting, and economics." }
    ];

    // Simple Calendar Helpers
    const daysInMonth = (month, year) => new Date(year, month + 1, 0).getDate();
    const firstDayOfMonth = (month, year) => new Date(year, month, 1).getDay();

    const renderCalendar = () => {
        const month = date.getMonth();
        const year = date.getFullYear();
        const days = daysInMonth(month, year);
        const firstDay = firstDayOfMonth(month, year);

        const calendarDays = [];

        // Empty slots for previous month
        for (let i = 0; i < firstDay; i++) {
            calendarDays.push(<div key={`empty-${i}`} className="calendar-day-empty"></div>);
        }

        // Days of current month
        for (let i = 1; i <= days; i++) {
            const isToday = i === new Date().getDate() && month === new Date().getMonth();
            calendarDays.push(
                <div key={i} className={`calendar-day ${isToday ? 'today' : ''}`}>
                    {i}
                </div>
            );
        }

        return calendarDays;
    };

    const handleCourseClick = () => {
        navigate('/login');
    };

    return (
        <div className="page-container">
            {/* Top Header Section */}
            <header className="header">
                <div className="logo-container">
                    <FaGraduationCap className="logo-icon" />
                    <span className="logo-text">E-LEARN</span>
                </div>
                <div className="header-content">
                    <h1 className="college-name">VIVEK COLLEGE OF COMMERCE</h1>
                    <h3 className="sub-text">(Autonomous)</h3>
                    <div className="auth-params">
                        <button onClick={() => navigate('/login')} className="login-btn">Login / Sign Up</button>
                    </div>
                </div>
            </header>

            {/* Main Content */}
            <div className="main-content">

                {/* Courses Dropdown Section */}
                <div
                    className="dropdown-container"
                    onMouseEnter={() => setShowCourses(true)}
                    onMouseLeave={() => setShowCourses(false)}
                >
                    <button
                        className="dropdown-button"
                    >
                        <FaBookOpen style={{ marginRight: '10px' }} />
                        View Our Courses
                    </button>

                    {showCourses && (
                        <div className="dropdown-menu">
                            {courses.map(course => (
                                <div
                                    key={course.id}
                                    className={`dropdown-item ${hoveredCourseId === course.id ? 'hovered' : ''}`}
                                    onClick={handleCourseClick}
                                    onMouseEnter={() => setHoveredCourseId(course.id)}
                                    onMouseLeave={() => setHoveredCourseId(null)}
                                >
                                    <div>{course.title}</div>
                                    {hoveredCourseId === course.id && (
                                        <div className="course-description">
                                            {course.description}
                                        </div>
                                    )}
                                </div>
                            ))}
                        </div>
                    )}
                </div>

                {/* Calendar Section Wrapper */}
                <div>
                    <h2 className="section-title">
                        <FaCalendarAlt style={{ marginRight: '10px' }} />
                        Academic Calendar - {date.toLocaleString('default', { month: 'long' })} {date.getFullYear()}
                    </h2>
                    <div className="calendar-container">
                        <div className="week-days">
                            <div>Sun</div><div>Mon</div><div>Tue</div><div>Wed</div><div>Thu</div><div>Fri</div><div>Sat</div>
                        </div>
                        <div className="calendar-grid">
                            {renderCalendar()}
                        </div>
                    </div>
                </div>

            </div>
        </div>
    );
};

export default Home;
